#!/bin/bash

# Direct EMR Step Addition for Spark FIS Processing
# No validation - just add the step directly

CLUSTER_ID=${1:-<EMR-CLUSTER-ID>}
REGION=${2:-us-east-2}

echo "=== DIRECT SPARK STEP ADDITION ==="
echo "Cluster: $CLUSTER_ID"
echo "Region: $REGION"
echo ""

# Create a minimal step JSON that creates the script and runs it
cat > /tmp/spark_step_direct.json << 'EOF'
[
  {
    "Name": "Spark FIS Processing Direct",
    "ActionOnFailure": "CONTINUE",
    "Type": "CUSTOM_JAR",
    "Jar": "command-runner.jar",
    "Args": [
      "bash", "-c",
      "echo 'Creating Spark FIS script...' && cat > /tmp/spark_fis_direct.py << 'PYTHON_EOF' && echo '#!/usr/bin/env python3' > /tmp/spark_fis_direct.py && echo 'import os, sys, json, numpy as np, rasterio, boto3, skfuzzy as fuzz' >> /tmp/spark_fis_direct.py && echo 'from skfuzzy import control as ctrl' >> /tmp/spark_fis_direct.py && echo 'from pyspark.sql import SparkSession' >> /tmp/spark_fis_direct.py && echo 'def create_fuzzy_system(config):' >> /tmp/spark_fis_direct.py && echo '    resolution = 25' >> /tmp/spark_fis_direct.py && echo '    input_vars = {}' >> /tmp/spark_fis_direct.py && echo '    for var_name, var_config in config[\"input_variables\"].items():' >> /tmp/spark_fis_direct.py && echo '        universe = np.linspace(var_config[\"min\"], var_config[\"max\"], resolution)' >> /tmp/spark_fis_direct.py && echo '        input_vars[var_name] = ctrl.Antecedent(universe, var_name)' >> /tmp/spark_fis_direct.py && echo '        for mf_name, mf_config in var_config[\"membership_functions\"].items():' >> /tmp/spark_fis_direct.py && echo '            if mf_config[\"type\"] == \"trapmf\":' >> /tmp/spark_fis_direct.py && echo '                input_vars[var_name][mf_name] = fuzz.trapmf(input_vars[var_name].universe, mf_config[\"params\"])' >> /tmp/spark_fis_direct.py && echo '            elif mf_config[\"type\"] == \"trimf\":' >> /tmp/spark_fis_direct.py && echo '                input_vars[var_name][mf_name] = fuzz.trimf(input_vars[var_name].universe, mf_config[\"params\"])' >> /tmp/spark_fis_direct.py && echo '    output_config = config[\"output_variable\"]' >> /tmp/spark_fis_direct.py && echo '    universe = np.linspace(output_config[\"min\"], output_config[\"max\"], resolution)' >> /tmp/spark_fis_direct.py && echo '    output_var = ctrl.Consequent(universe, output_config[\"name\"])' >> /tmp/spark_fis_direct.py && echo '    for mf_name, mf_config in output_config[\"membership_functions\"].items():' >> /tmp/spark_fis_direct.py && echo '        if mf_config[\"type\"] == \"trapmf\":' >> /tmp/spark_fis_direct.py && echo '            output_var[mf_name] = fuzz.trapmf(output_var.universe, mf_config[\"params\"])' >> /tmp/spark_fis_direct.py && echo '        elif mf_config[\"type\"] == \"trimf\":' >> /tmp/spark_fis_direct.py && echo '            output_var[mf_name] = fuzz.trimf(output_var.universe, mf_config[\"params\"])' >> /tmp/spark_fis_direct.py && echo '    rules = []' >> /tmp/spark_fis_direct.py && echo '    for rule_config in config[\"rules\"]:' >> /tmp/spark_fis_direct.py && echo '        antecedent = rule_config[\"antecedent\"]' >> /tmp/spark_fis_direct.py && echo '        consequent = rule_config[\"consequent\"]' >> /tmp/spark_fis_direct.py && echo '        antecedent_conditions = []' >> /tmp/spark_fis_direct.py && echo '        for condition in antecedent:' >> /tmp/spark_fis_direct.py && echo '            var_name = condition[\"variable\"]' >> /tmp/spark_fis_direct.py && echo '            membership = condition[\"membership\"]' >> /tmp/spark_fis_direct.py && echo '            antecedent_conditions.append(input_vars[var_name][membership])' >> /tmp/spark_fis_direct.py && echo '        if len(antecedent_conditions) == 1:' >> /tmp/spark_fis_direct.py && echo '            rule = ctrl.Rule(antecedent_conditions[0], output_var[consequent])' >> /tmp/spark_fis_direct.py && echo '        else:' >> /tmp/spark_fis_direct.py && echo '            combined = antecedent_conditions[0]' >> /tmp/spark_fis_direct.py && echo '            for condition in antecedent_conditions[1:]:' >> /tmp/spark_fis_direct.py && echo '                combined = combined & condition' >> /tmp/spark_fis_direct.py && echo '            rule = ctrl.Rule(combined, output_var[consequent])' >> /tmp/spark_fis_direct.py && echo '        rules.append(rule)' >> /tmp/spark_fis_direct.py && echo '    control_system = ctrl.ControlSystem(rules)' >> /tmp/spark_fis_direct.py && echo '    simulation = ctrl.ControlSystemSimulation(control_system)' >> /tmp/spark_fis_direct.py && echo '    return simulation, list(config[\"input_variables\"].keys()), output_config[\"name\"]' >> /tmp/spark_fis_direct.py && echo 'def process_small_block_spark(chunk_data):' >> /tmp/spark_fis_direct.py && echo '    config, start_row, end_row, start_col, end_col, social_data, env_data, strat_data, nodata_value = chunk_data' >> /tmp/spark_fis_direct.py && echo '    simulation, input_vars, output_var_name = create_fuzzy_system(config)' >> /tmp/spark_fis_direct.py && echo '    social_block = social_data[start_row:end_row, start_col:end_col]' >> /tmp/spark_fis_direct.py && echo '    env_block = env_data[start_row:end_row, start_col:end_col]' >> /tmp/spark_fis_direct.py && echo '    strat_block = strat_data[start_row:end_row, start_col:end_col]' >> /tmp/spark_fis_direct.py && echo '    rows, cols = social_block.shape' >> /tmp/spark_fis_direct.py && echo '    result_block = np.full((rows, cols), nodata_value, dtype=np.float32)' >> /tmp/spark_fis_direct.py && echo '    for i in range(rows):' >> /tmp/spark_fis_direct.py && echo '        for j in range(cols):' >> /tmp/spark_fis_direct.py && echo '            if (social_block[i, j] == nodata_value or env_block[i, j] == nodata_value or strat_block[i, j] == nodata_value):' >> /tmp/spark_fis_direct.py && echo '                continue' >> /tmp/spark_fis_direct.py && echo '            simulation.input[input_vars[0]] = float(social_block[i, j])' >> /tmp/spark_fis_direct.py && echo '            simulation.input[input_vars[1]] = float(env_block[i, j])' >> /tmp/spark_fis_direct.py && echo '            simulation.input[input_vars[2]] = float(strat_block[i, j])' >> /tmp/spark_fis_direct.py && echo '            simulation.compute()' >> /tmp/spark_fis_direct.py && echo '            result_block[i, j] = float(simulation.output[output_var_name])' >> /tmp/spark_fis_direct.py && echo '    return (start_row, end_row, start_col, end_col, result_block)' >> /tmp/spark_fis_direct.py && echo 'def process_config_spark_submit(config_name):' >> /tmp/spark_fis_direct.py && echo '    print(f\"Processing {config_name} with Spark Submit FIS\")' >> /tmp/spark_fis_direct.py && echo '    s3 = boto3.client(\"s3\")' >> /tmp/spark_fis_direct.py && echo '    bucket = \"<AWS-BUCKET>-unifile\"' >> /tmp/spark_fis_direct.py && echo '    prefix = \"unifile_test/\"' >> /tmp/spark_fis_direct.py && echo '    s3.download_file(bucket, prefix + config_name, f\"/tmp/{config_name}\")' >> /tmp/spark_fis_direct.py && echo '    with open(f\"/tmp/{config_name}\", \"r\") as f:' >> /tmp/spark_fis_direct.py && echo '        config = json.load(f)' >> /tmp/spark_fis_direct.py && echo '    with rasterio.open(\"/tmp/social.tif\") as src:' >> /tmp/spark_fis_direct.py && echo '        social_data = src.read(1)' >> /tmp/spark_fis_direct.py && echo '        profile = src.profile' >> /tmp/spark_fis_direct.py && echo '        height, width = social_data.shape' >> /tmp/spark_fis_direct.py && echo '    with rasterio.open(\"/tmp/environmental.tif\") as src:' >> /tmp/spark_fis_direct.py && echo '        env_data = src.read(1)' >> /tmp/spark_fis_direct.py && echo '    with rasterio.open(\"/tmp/strategic.tif\") as src:' >> /tmp/spark_fis_direct.py && echo '        strat_data = src.read(1)' >> /tmp/spark_fis_direct.py && echo '    print(f\"Processing {height}x{width} raster with Spark Submit FIS...\")' >> /tmp/spark_fis_direct.py && echo '    spark = SparkSession.builder.appName(f\"FIS-Submit-{config_name}\").config(\"spark.sql.adaptive.enabled\", \"true\").config(\"spark.serializer\", \"org.apache.spark.serializer.KryoSerializer\").config(\"spark.kryo.registrationRequired\", \"false\").config(\"spark.executor.memory\", \"4g\").config(\"spark.executor.cores\", \"2\").config(\"spark.driver.memory\", \"2g\").getOrCreate()' >> /tmp/spark_fis_direct.py && echo '    sc = spark.sparkContext' >> /tmp/spark_fis_direct.py && echo '    block_size = 100' >> /tmp/spark_fis_direct.py && echo '    chunks = []' >> /tmp/spark_fis_direct.py && echo '    for start_row in range(0, height, block_size):' >> /tmp/spark_fis_direct.py && echo '        end_row = min(start_row + block_size, height)' >> /tmp/spark_fis_direct.py && echo '        for start_col in range(0, width, block_size):' >> /tmp/spark_fis_direct.py && echo '            end_col = min(start_col + block_size, width)' >> /tmp/spark_fis_direct.py && echo '            social_block = social_data[start_row:end_row, start_col:end_col]' >> /tmp/spark_fis_direct.py && echo '            env_block = env_data[start_row:end_row, start_col:end_col]' >> /tmp/spark_fis_direct.py && echo '            strat_block = strat_data[start_row:end_row, start_col:end_col]' >> /tmp/spark_fis_direct.py && echo '            chunks.append((config, start_row, end_row, start_col, end_col, social_block, env_block, strat_block, 5.0))' >> /tmp/spark_fis_direct.py && echo '    print(f\"Created {len(chunks)} small blocks for Spark processing\")' >> /tmp/spark_fis_direct.py && echo '    num_partitions = max(50, len(chunks) // 10)' >> /tmp/spark_fis_direct.py && echo '    rdd = sc.parallelize(chunks, numSlices=num_partitions)' >> /tmp/spark_fis_direct.py && echo '    results = rdd.map(process_small_block_spark).collect()' >> /tmp/spark_fis_direct.py && echo '    result_data = np.full((height, width), 5.0, dtype=np.float32)' >> /tmp/spark_fis_direct.py && echo '    for start_row, end_row, start_col, end_col, result_block in results:' >> /tmp/spark_fis_direct.py && echo '        result_data[start_row:end_row, start_col:end_col] = result_block' >> /tmp/spark_fis_direct.py && echo '    config_base = config_name.replace(\".json\", \"\")' >> /tmp/spark_fis_direct.py && echo '    output_name = f\"result_spark_submit_{config_base}.tif\"' >> /tmp/spark_fis_direct.py && echo '    output_path = f\"/tmp/{output_name}\"' >> /tmp/spark_fis_direct.py && echo '    profile.update(dtype=np.float32, count=1)' >> /tmp/spark_fis_direct.py && echo '    with rasterio.open(output_path, \"w\", **profile) as dst:' >> /tmp/spark_fis_direct.py && echo '        dst.write(result_data, 1)' >> /tmp/spark_fis_direct.py && echo '    s3.upload_file(output_path, bucket, prefix + output_name)' >> /tmp/spark_fis_direct.py && echo '    print(f\"Completed {config_name} -> {output_name}\")' >> /tmp/spark_fis_direct.py && echo '    spark.stop()' >> /tmp/spark_fis_direct.py && echo '    return True' >> /tmp/spark_fis_direct.py && echo 'def main():' >> /tmp/spark_fis_direct.py && echo '    print(\"=== SPARK SUBMIT FIS PROCESSING STARTED ===\")' >> /tmp/spark_fis_direct.py && echo '    configs = [\"config_median.json\", \"config_minimum.json\", \"config_mode.json\", \"config_round_down.json\", \"config_round_up.json\"]' >> /tmp/spark_fis_direct.py && echo '    for i, config in enumerate(configs, 1):' >> /tmp/spark_fis_direct.py && echo '        print(f\"--- Config {i}/{len(configs)} ---\")' >> /tmp/spark_fis_direct.py && echo '        try:' >> /tmp/spark_fis_direct.py && echo '            process_config_spark_submit(config)' >> /tmp/spark_fis_direct.py && echo '            print(f\"SUCCESS: {config}\")' >> /tmp/spark_fis_direct.py && echo '        except Exception as e:' >> /tmp/spark_fis_direct.py && echo '            print(f\"ERROR: {config} - {e}\")' >> /tmp/spark_fis_direct.py && echo '            continue' >> /tmp/spark_fis_direct.py && echo '    print(\"=== SPARK SUBMIT FIS PROCESSING COMPLETED ===\")' >> /tmp/spark_fis_direct.py && echo 'if __name__ == \"__main__\":' >> /tmp/spark_fis_direct.py && echo '    main()' >> /tmp/spark_fis_direct.py && echo 'PYTHON_EOF' && chmod +x /tmp/spark_fis_direct.py && echo 'Installing packages...' && pip3 install rasterio scikit-fuzzy boto3 networkx pyspark && echo 'Downloading input files...' && aws s3 cp s3://<AWS-BUCKET>-unifile/unifile_test/so300m.in /tmp/social.tif && aws s3 cp s3://<AWS-BUCKET>-unifile/unifile_test/e300m.in /tmp/environmental.tif && aws s3 cp s3://<AWS-BUCKET>-unifile/unifile_test/s300m.in /tmp/strategic.tif && echo 'Running Spark Submit FIS processing...' && spark-submit --master yarn --deploy-mode cluster --executor-memory 4g --executor-cores 2 --driver-memory 2g --conf spark.sql.adaptive.enabled=true --conf spark.serializer=org.apache.spark.serializer.KryoSerializer --conf spark.kryo.registrationRequired=false --conf spark.driver.maxResultSize=1g /tmp/spark_fis_direct.py && echo '=== SPARK SUBMIT FIS PROCESSING COMPLETED ==='"
    ]
  }
]
EOF

echo "Adding EMR step directly..."
aws emr add-steps --cluster-id "$CLUSTER_ID" --region "$REGION" --steps file:///tmp/spark_step_direct.json

echo ""
echo "Step added successfully!"
echo "Check the EMR console to monitor progress." 